import yaml
import os
import re
import json

def update_wp_url(filepath, new_urls):
    if not os.path.exists(filepath):
        print(f"File not found: {filepath}")
        return
    
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()
    
    # Split frontmatter and body
    parts = content.split('---', 2)
    if len(parts) < 3:
        print(f"No frontmatter found in {filepath}")
        return
    
    frontmatter_str = parts[1]
    body = parts[2]
    
    try:
        # Parse the frontmatter to get current urls
        data = yaml.safe_load(frontmatter_str)
        current_urls = data.get('wp_url', [])
        if current_urls is None: current_urls = []
        if isinstance(current_urls, str): current_urls = [current_urls]
        
        # Merge and unique
        all_urls = list(set(current_urls + new_urls))
        
        # Sort: helpcenter first, then support, then others
        def sort_key(url):
            if 'helpcenter' in url:
                return (0, url)
            elif 'support' in url:
                return (1, url)
            else:
                return (2, url)
        
        all_urls.sort(key=sort_key)
        
        # Construct the new wp_url section
        if not all_urls:
            new_wp_url_section = "wp_url: []"
        else:
            new_wp_url_section = "wp_url:\n"
            for url in all_urls:
                new_wp_url_section += f"  - {url}\n"
        
        # Find the old wp_url section in frontmatter_str
        match = re.search(r'wp_url:.*?(?=\n\S+:|\n$)', frontmatter_str, re.DOTALL)
        
        if match:
            old_section = match.group(0).strip()
            new_section = new_wp_url_section.strip()
            if old_section != new_section:
                print(f"UPDATE_FILE: {filepath}")
                print(f"OLD_STR:\n{old_section}")
                print(f"NEW_STR:\n{new_section}")
                print("---")
        else:
            # If wp_url doesn't exist, add it before the end of frontmatter
            print(f"UPDATE_FILE: {filepath}")
            print(f"OLD_STR: ---") # Placeholder for adding
            print(f"NEW_STR: {new_wp_url_section.strip()}\n---")
            print("---")

    except Exception as e:
        print(f"Error processing {filepath}: {e}")

